    void frame(String title,boolean inner){screenToken++;root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);setContentView(root);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(9),dp(7),dp(9),dp(7));bar.setBackground(grad(navy,navy2,0));TextView nav=tv(inner?"‹":"☰",31,white);nav.setGravity(Gravity.CENTER);bar.addView(nav,new LinearLayout.LayoutParams(dp(52),dp(50)));TextView t=tv(title,18,white);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);bar.addView(t,new LinearLayout.LayoutParams(0,dp(50),1));TextView brand=tv("ساختمان‌یار",12,Color.rgb(190,224,220));brand.setGravity(Gravity.CENTER);bar.addView(brand,new LinearLayout.LayoutParams(dp(92),dp(50)));root.addView(bar,new LinearLayout.LayoutParams(-1,dp(66)));ScrollView sv=new ScrollView(this);sv.setFillViewport(true);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(16),dp(16),dp(16),dp(32));content.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);sv.addView(content);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));drawer=new LinearLayout(this);drawer.setOrientation(LinearLayout.VERTICAL);drawer.setPadding(dp(14),dp(16),dp(14),dp(22));drawer.setBackgroundColor(white);drawer.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);root.addView(drawer,new LinearLayout.LayoutParams((int)(getResources().getDisplayMetrics().widthPixels*.86),-1));drawer.setVisibility(View.GONE);nav.setOnClickListener(v->{if(inner)backPage();else toggleDrawer();});}
    void toggleDrawer(){if(drawer!=null)drawer.setVisibility(drawer.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE);}
    void open(String id){if(history.isEmpty()||!history.peekLast().equals(id))history.addLast(id);show(id);}
    void show(String id){if("manager".equals(id))managerHome();else if("units".equals(id))units();else if("charges".equals(id))charges();else if("repairs".equals(id))repairs();else if("payments".equals(id))payments();else if("plans".equals(id))plans();else if("resident".equals(id))residentHome();else if("resident_pay".equals(id))residentPay();else if("admin".equals(id))adminHome();else if("admin_buildings".equals(id))adminBuildings();else if("admin_plans".equals(id))adminPlans();else if("admin_settings".equals(id))adminSettings();else showLogin();}
    void backPage(){if(drawer!=null&&drawer.getVisibility()==View.VISIBLE){drawer.setVisibility(View.GONE);return;}if(history.size()>1){history.removeLast();show(history.peekLast());}else logout();}
    void logout(){session="";role="";history.clear();showLogin();}
    void showLogin(){role="";session="";history.clear();frame("ورود",false);content.setGravity(Gravity.CENTER_HORIZONTAL);content.addView(gap(8));LinearLayout hero=new LinearLayout(this);hero.setOrientation(LinearLayout.VERTICAL);hero.setGravity(Gravity.CENTER);hero.setPadding(dp(22),dp(22),dp(22),dp(22));hero.setBackground(grad(navy,teal,28));TextView logo=tv("ساختمان‌یار",31,white);logo.setGravity(Gravity.CENTER);logo.setTypeface(Typeface.DEFAULT,Typeface.BOLD);hero.addView(logo);TextView sub=tv("مدیریت ساختمان، شفاف و یکپارچه",14,Color.rgb(215,237,234));sub.setGravity(Gravity.CENTER);hero.addView(sub);content.addView(hero,new LinearLayout.LayoutParams(-1,dp(145)));content.addView(gap(20));TextView h=tv("ورود به حساب",23,navy);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);content.addView(h,new LinearLayout.LayoutParams(-1,dp(42)));content.addView(tv("نقش خود را انتخاب کنید",12,muted),new LinearLayout.LayoutParams(-1,dp(30)));EditText u=input("نام کاربری"),p=input("رمز عبور");p.setInputType(129);content.addView(u,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(9));content.addView(p,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(14));Button m=btn("ورود مدیر ساختمان  ›",teal),r=btn("ورود ساکن  ›",blue),a=btn("ورود مدیرکل سامانه  🔐",navy);content.addView(m,new LinearLayout.LayoutParams(-1,dp(55)));content.addView(gap(9));content.addView(r,new LinearLayout.LayoutParams(-1,dp(55)));content.addView(gap(9));content.addView(a,new LinearLayout.LayoutParams(-1,dp(52)));content.addView(gap(16));TextView q=tv("ساختمان هنوز در سامانه ثبت نشده؟",12,muted);q.setGravity(Gravity.CENTER);content.addView(q,new LinearLayout.LayoutParams(-1,dp(30)));Button reg=btn("＋ ثبت ساختمان و مدیر جدید",Color.rgb(86,106,119));content.addView(reg,new LinearLayout.LayoutParams(-1,dp(52)));m.setOnClickListener(v->login(u.getText().toString().trim(),p.getText().toString(),"manager"));r.setOnClickListener(v->login(u.getText().toString().trim(),p.getText().toString(),"resident"));a.setOnClickListener(v->startActivity(new Intent(this,AdminActivity.class)));reg.setOnClickListener(v->register());}
    void drawerHead(String title,String sub,int accent){drawer.removeAllViews();LinearLayout h=new LinearLayout(this);h.setOrientation(LinearLayout.VERTICAL);h.setPadding(dp(17),dp(15),dp(17),dp(15));h.setBackground(grad(navy,accent,21));TextView a=tv("ساختمان‌یار",21,white);a.setTypeface(Typeface.DEFAULT,Typeface.BOLD);h.addView(a);h.addView(tv(title,13,Color.rgb(218,235,234)));h.addView(tv(sub,11,Color.rgb(180,211,210)));drawer.addView(h,new LinearLayout.LayoutParams(-1,dp(101)));drawer.addView(gap(12));}
