    void login(String u,String p,String r){if(u.isEmpty()||p.isEmpty()){toast("نام کاربری و رمز عبور را وارد کنید");return;}final int t=screenToken;io.submit(()->{try{JSONObject b=new JSONObject().put("action",r.equals("resident")?"login_resident":"login_manager").put("username",u).put("password",p);JSONObject j=new JSONObject(post(b,null));if(j.has("error"))throw new Exception(j.getString("error"));session=j.getString("session");role=r;history.clear();history.addLast(r.equals("resident")?"resident":"manager");runOnUiThread(()->{if(t!=screenToken)return;if("resident".equals(r))residentHome();else managerHome();});}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}});}
    void register(){frame("ثبت ساختمان",true);section("شروع کار با ساختمان‌یار","ساختمان و حساب مدیر را یکجا بسازید");EditText n=input("نام ساختمان"),a=input("آدرس ساختمان"),u=input("نام کاربری مدیر"),p=input("رمز عبور حداقل ۶ کاراکتر");p.setInputType(129);for(EditText e:new EditText[]{n,a,u,p}){content.addView(e,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(9));}Button b=btn("ثبت ساختمان و ورود",teal);content.addView(b,new LinearLayout.LayoutParams(-1,dp(56)));b.setOnClickListener(v->io.submit(()->{try{JSONObject j=new JSONObject().put("action","register_manager").put("building_name",n.getText().toString()).put("address",a.getText().toString()).put("username",u.getText().toString()).put("password",p.getText().toString());JSONObject z=new JSONObject(post(j,null));if(z.has("error"))throw new Exception(z.getString("error"));session=z.getString("session");role="manager";history.clear();history.addLast("manager");runOnUiThread(this::managerHome);}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}}));}
    void managerHome(){frame("داشبورد مدیر",false);managerDrawer();hero("داشبورد ساختمان","امروز: "+JalaliDate.now()+"  •  همه تاریخ‌ها شمسی نمایش داده می‌شوند",teal);loadDashboard();}
    void loadDashboard(){call("dashboard",j->{JSONArray u=j.optJSONArray("units"),c=j.optJSONArray("charges"),p=j.optJSONArray("payments"),r=j.optJSONArray("repairs");statRow("واحدها",String.valueOf(u==null?0:u.length()),"تعمیرات",String.valueOf(r==null?0:r.length()));statRow("شارژها",String.valueOf(c==null?0:c.length()),"پرداخت‌ها",String.valueOf(p==null?0:p.length()));section("دسترسی سریع","مدیریت بخش‌های اصلی ساختمان");action("واحدها و ساکنان","ساخت واحد، ثبت ساکن و اطلاعات حساب","▣","units",blue);action("شارژ و هزینه‌ها","ثبت شارژ و هزینه ساختمان","₮","charges",gold);action("تعمیرات","ثبت و پیگیری هزینه تعمیرات","⚒","repairs",red);action("پرداخت‌ها","بررسی و تأیید پرداخت‌های ساکنان","✓","payments",green);action("اشتراک سامانه","مشاهده طرح‌ها و درخواست اشتراک","★","plans",teal2);});}
    void units(){frame("واحدها و ساکنان",true);managerDrawer();section("مدیریت واحدها","افزودن واحد و ساخت حساب ساکن");Button add=btn("＋ افزودن واحد",teal);content.addView(add,new LinearLayout.LayoutParams(-1,dp(54)));content.addView(gap(11));add.setOnClickListener(v->addUnitDialog());call("dashboard",j->{JSONArray a=j.optJSONArray("units");if(a==null||a.length()==0){empty("هنوز واحدی ثبت نشده است");return;}for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x==null)continue;unitCard(x);}});}
    void unitCard(JSONObject x){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(15),dp(12),dp(15),dp(12));c.setBackground(box(white,19));TextView n=tv("واحد "+x.optString("unit_no","-"),18,navy);n.setTypeface(Typeface.DEFAULT,Typeface.BOLD);c.addView(n);c.addView(tv("مالک / ساکن: "+x.optString("owner_name","ثبت نشده"),12,muted));c.addView(tv("تعداد ساکنان: "+x.optString("resident_count","0"),12,muted));Button r=btn("＋ ساخت حساب ساکن",blue);c.addView(r,new LinearLayout.LayoutParams(-1,dp(46)));r.setOnClickListener(v->residentDialog(x.optString("id"),x.optString("unit_no")));content.addView(c,new LinearLayout.LayoutParams(-1,dp(145)));content.addView(gap(9));}
    void addUnitDialog(){final EditText no=input("شماره واحد"),cnt=input("تعداد ساکنان"),name=input("نام مالک / ساکن");LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(10),0,dp(10),0);l.addView(no,new LinearLayout.LayoutParams(-1,dp(54)));l.addView(gap(7));l.addView(cnt,new LinearLayout.LayoutParams(-1,dp(54)));l.addView(gap(7));l.addView(name,new LinearLayout.LayoutParams(-1,dp(54)));new AlertDialog.Builder(this).setTitle("افزودن واحد").setView(l).setNegativeButton("لغو",null).setPositiveButton("ذخیره",(d,w)->callObj(new JSONObject().put("action","add_unit").put("unit_no",no.getText().toString()).put("residents_count",cnt.getText().toString()).put("resident_name",name.getText().toString()),z->{toast("واحد ثبت شد");units();})).show();}
    void residentDialog(String unitId,String unitNo){final EditText n=input("نام و نام خانوادگی"),u=input("نام کاربری ساکن"),p=input("رمز عبور حداقل ۶ کاراکتر");p.setInputType(129);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(10),0,dp(10),0);for(EditText e:new EditText[]{n,u,p}){l.addView(e,new LinearLayout.LayoutParams(-1,dp(54)));l.addView(gap(7));}new AlertDialog.Builder(this).setTitle("حساب ساکن • واحد "+unitNo).setView(l).setNegativeButton("لغو",null).setPositiveButton("ساخت حساب",(d,w)->callObj(new JSONObject().put("action","create_resident").put("unit_id",unitId).put("username",u.getText().toString()).put("password",p.getText().toString()).put("full_name",n.getText().toString()),z->toast("حساب ساکن ساخته شد"))).show();}
    void charges(){frame("شارژ و هزینه‌ها",true);managerDrawer();section("ثبت شارژ و هزینه","مبلغ به ریال ذخیره و در برنامه به تومان نمایش داده می‌شود");Button add=btn("＋ ثبت شارژ / هزینه",gold);content.addView(add,new LinearLayout.LayoutParams(-1,dp(54)));content.addView(gap(12));add.setOnClickListener(v->chargeDialog());call("dashboard",j->{JSONArray a=j.optJSONArray("charges");if(a==null||a.length()==0){empty("هنوز شارژ یا هزینه‌ای ثبت نشده است");return;}section("سوابق ثبت‌شده",null);for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null)item(x.optString("title","هزینه"),money(x.optDouble("amount_rial"))+"  •  "+JalaliDate.format(x.optString("created_at")));}});}
    void chargeDialog(){final EditText t=input("عنوان شارژ / هزینه"),a=input("مبلغ به تومان"),d=input("توضیحات");LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(10),0,dp(10),0);for(EditText e:new EditText[]{t,a,d}){l.addView(e,new LinearLayout.LayoutParams(-1,dp(54)));l.addView(gap(7));}new AlertDialog.Builder(this).setTitle("ثبت شارژ یا هزینه").setView(l).setNegativeButton("لغو",null).setPositiveButton("ثبت",(x,w)->{long rial=Math.max(0,parseMoney(a.getText().toString())*10);callObj(new JSONObject().put("action","add_charge").put("title",t.getText().toString()).put("amount_rial",rial).put("description",d.getText().toString()).put("allocation_method","per_unit"),z->{toast("هزینه ثبت شد");charges();});}).show();}
